  import { z } from 'zod';
  const BalanceDataSchema = z.object({ balance: z.number(), loginStreak: z.number(), lastLoginReward: z.string().nullable() });
  export async function balanceFetcher(url: string): Promise<BalanceData> {
    const res = await fetch(url);
    if (!res.ok) throw new Error('Failed to fetch balance');
    return BalanceDataSchema.parse(await res.json());
  }

